begin;
create temporary table dm_fixture(caller uuid,callee uuid,outsider uuid,convo uuid)on commit drop;
insert into dm_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid();grant select on dm_fixture to authenticated;
insert into auth.users(id,aud,role,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at)select u,'authenticated','authenticated','qa-'||u||'@example.invalid',jsonb_build_object('display_name','QA_'||substr(replace(u::text,'-',''),1,16)),'{}'::jsonb,now(),now()from dm_fixture cross join lateral unnest(array[caller,callee,outsider])u;
insert into public.friendships(requester_id,recipient_id,status)select caller,callee,'accepted' from dm_fixture;
insert into public.conversations(id,user_a,user_b)select convo,least(caller,callee),greatest(caller,callee) from dm_fixture;
set local role authenticated;
do $$declare f record;e public.call_events;e2 public.call_events;denied boolean;begin select * into f from dm_fixture;
 perform set_config('request.jwt.claim.sub',f.caller::text,true);
 insert into public.call_events(conversation_id,caller_id,kind)values(f.convo,f.caller,'video')returning * into e;
 if e.status<>'ringing' or e.kind<>'video' then raise exception'New call must ring';end if;
 denied:=false;begin insert into public.call_events(conversation_id,caller_id,status)values(f.convo,f.caller,'accepted');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Caller forged status';end if;
 denied:=false;begin update public.call_events set status='accepted' where id=e.id;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Direct update allowed';end if;
 denied:=false;begin perform public.call_event_transition(e.id,'accepted');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Caller answered own call';end if;
 perform set_config('request.jwt.claim.sub',f.outsider::text,true);
 if exists(select 1 from public.call_events where id=e.id)then raise exception'Outsider read call';end if;
 denied:=false;begin perform public.call_event_transition(e.id,'accepted');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Outsider answered';end if;
 denied:=false;begin insert into public.call_events(conversation_id,caller_id)values(f.convo,f.outsider);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Outsider rang';end if;
 if public.can_call_conversation(f.convo) then raise exception'Outsider may join room';end if;
 perform set_config('request.jwt.claim.sub',f.callee::text,true);
 denied:=false;begin perform public.call_event_transition(e.id,'canceled');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Callee canceled';end if;
 e2:=public.call_event_transition(e.id,'accepted');if e2.status<>'accepted' or e2.answered_at is null then raise exception'Accept failed';end if;
 denied:=false;begin perform public.call_event_transition(e.id,'declined');exception when invalid_parameter_value then denied:=true;end;if not denied then raise exception'Declined after accept';end if;
 e2:=public.call_event_transition(e.id,'ended');if e2.status<>'ended' or e2.ended_at is null or e2.ended_by<>f.callee then raise exception'End failed';end if;
 perform set_config('request.jwt.claim.sub',f.caller::text,true);
 insert into public.call_events(conversation_id,caller_id)values(f.convo,f.caller)returning * into e;
 e2:=public.call_event_transition(e.id,'canceled');if e2.status<>'canceled' then raise exception'Cancel failed';end if;
 insert into public.call_events(conversation_id,caller_id)values(f.convo,f.caller)returning * into e;
 e2:=public.call_event_transition(e.id,'missed');if e2.status<>'missed' then raise exception'Timeout failed';end if;
 insert into public.call_events(conversation_id,caller_id)values(f.convo,f.caller)returning * into e;
 perform set_config('request.jwt.claim.sub',f.callee::text,true);
 denied:=false;begin perform public.call_event_transition(e.id,'missed');exception when invalid_parameter_value then denied:=true;end;if not denied then raise exception'Callee expired a ringing call early';end if;
 e2:=public.call_event_transition(e.id,'declined');if e2.status<>'declined' then raise exception'Decline failed';end if;
end $$;
reset role;
rollback;
